AGE_MID = np.array([1, 6, 15, 25, 35, 45, 55, 65, 75], np.float32)
def _md5(p):
    try:
        return hashlib.md5(Path(p).read_bytes()).hexdigest()
    except Exception:
        return None
def _cached_map(paths, fn, dim, batch=16):
    """Embed unique files once, in batches; unreadable -> NaN row (filled with a train constant later)."""
    keys = [_md5(p) for p in paths]
    uniq = {}
    for p, k in zip(paths, keys):
        if k is not None and k not in uniq:
            uniq[k] = p
    items = list(uniq.items()); emb = {}
    for lo in range(0, len(items), batch):
        chunk = items[lo:lo + batch]
        out = fn([p for _, p in chunk])
        for (k, _), e in zip(chunk, out):
            emb[k] = e
        if (lo // batch) % 50 == 0:
            print(f'    {lo + len(chunk)}/{len(items)}', flush=True)
    nan = np.full(dim, np.nan, np.float32)
    X = np.stack([emb.get(k, nan) if k is not None else nan for k in keys]).astype(np.float32)
    return X
HF_REV = {'openai/whisper-large-v3': '06f233fe06e710322aca913c1bc4249a0d71fce1', 'nateraw/vit-age-classifier': '4b5acc345d9692c3ff4f45d250531afd3a3da0ef',
          'audeering/wav2vec2-large-robust-24-ft-age-gender': 'bad2737f529168bc3d3fcd97edfaba9583c7d36d',
          'openai/clip-vit-large-patch14': '32bd64288804d66eefd0ccbe215aa642df71cc41'}
class AgeExtractor:
    """Face: nateraw/vit-age-classifier (9 age groups -> expected age + probabilities).
    Voice: audeering/wav2vec2-large-robust-24-ft-age-gender (age 0..1 x 100, gender female/male/child)."""

    def __init__(self):
        import torch.nn as nn
        from transformers import AutoImageProcessor, ViTForImageClassification, Wav2Vec2FeatureExtractor, Wav2Vec2Model, Wav2Vec2PreTrainedModel
        fn = 'nateraw/vit-age-classifier'
        self.fp = AutoImageProcessor.from_pretrained(fn, revision=HF_REV[fn])
        self.fm = ViTForImageClassification.from_pretrained(fn, revision=HF_REV[fn]).to(DEVICE).eval()

        class Head(nn.Module):
            def __init__(self, c, n):
                super().__init__()
                self.dense = nn.Linear(c.hidden_size, c.hidden_size); self.dropout = nn.Dropout(c.final_dropout)
                self.out_proj = nn.Linear(c.hidden_size, n)

            def forward(self, x):
                return self.out_proj(self.dropout(torch.tanh(self.dense(self.dropout(x)))))

        class AgeGender(Wav2Vec2PreTrainedModel):  # model card of audeering/wav2vec2-large-robust-24-ft-age-gender
            def __init__(self, c):
                super().__init__(c)
                self.wav2vec2 = Wav2Vec2Model(c); self.age = Head(c, 1); self.gender = Head(c, 3)
                self.post_init()

            def forward(self, x):
                h = self.wav2vec2(x)[0].mean(1)
                return self.age(h), torch.softmax(self.gender(h), 1)

        name = 'audeering/wav2vec2-large-robust-24-ft-age-gender'
        self.vp = Wav2Vec2FeatureExtractor.from_pretrained(name, revision=HF_REV[name])
        self.vm = AgeGender.from_pretrained(name, revision=HF_REV[name]).to(DEVICE).eval()

    @torch.inference_mode()
    def faces(self, paths):
        def fn(ps):
            out = []
            for p in ps:
                try:
                    x = self.fp(Image.open(p).convert('RGB'), return_tensors='pt')['pixel_values'].to(DEVICE)
                    pr = torch.softmax(self.fm(x).logits, -1).float().cpu().numpy()[0]
                    out.append(np.r_[pr @ AGE_MID, pr])
                except Exception:
                    out.append(np.full(10, np.nan, np.float32))
            return out
        return _cached_map(paths, fn, 10)

    @torch.inference_mode()
    def voices(self, paths):
        def fn(ps):
            out = []
            for p in ps:
                w, st = load_wave(p)
                if w is None:
                    out.append(np.full(4, np.nan, np.float32)); continue
                x = self.vp(w, sampling_rate=16000, return_tensors='pt')['input_values'].to(DEVICE)
                a, g = self.vm(x)
                out.append(np.r_[100 * a.float().cpu().numpy()[0], g.float().cpu().numpy()[0]])  # age, p(female), p(male), p(child)
            return out
        return _cached_map(paths, fn, 4)
COND_L4 = ('p_face_male', 'p_voice_male', 'gender_agree', 'protocol_gender')
def fuser_matrix4(s, streams):
    cond = np.stack([s[k] for k in COND_L4], 1)
    st = np.stack([s[k] for k in streams], 1)
    return np.hstack([st, cond, (st[:, :, None] * cond[:, None, :]).reshape(len(st), -1)])
