VERSION = "RF-L2-002-v1"
class LoRAParam(nn.Module):
    def __init__(self, out_f, in_f, rank, alpha):
        super().__init__()
        self.A = nn.Parameter(torch.randn(rank, in_f, dtype=torch.float32) / rank)
        self.B = nn.Parameter(torch.zeros(out_f, rank, dtype=torch.float32))
        self.scale = alpha / rank

    def forward(self, W):
        return W + (self.B @ self.A).to(W.dtype) * self.scale
def add_lora(ib, MT, rank, alpha):
    import torch.nn.utils.parametrize as P
    for p in ib.parameters():
        p.requires_grad_(False)
    params = []
    for name, m in ib.modality_trunks[MT.AUDIO].named_modules():
        if isinstance(m, nn.MultiheadAttention):
            for mod, attr in ((m, 'in_proj_weight'), (m.out_proj, 'weight')):
                lp = LoRAParam(*getattr(mod, attr).shape, rank, alpha).to(DEVICE)
                P.register_parametrization(mod, attr, lp)
                params += [lp.A, lp.B]
    if not params:
        raise ValueError('no attention module found in the ImageBind audio trunk')
    return params
