class ProjQ(nn.Module):
    def __init__(self, df, dv, c):
        super().__init__()
        self.f = nn.Sequential(nn.LayerNorm(df), nn.Dropout(c['drop_f']), nn.Linear(df, c['dim']))
        self.v = nn.Sequential(nn.LayerNorm(dv), nn.Dropout(c['drop_v']), nn.Linear(dv, c['dim']))
def _u(X):
    return X / (np.linalg.norm(X, axis=1, keepdims=True) + 1e-8)
@torch.no_grad()
def t3_scores(models, clip, ibf, sam, r2, btc, ibv=None, mu_ib=None, ib_scale=0.5, vextra=()):
    """ibv given (RF-L2-022 projector QI): the raw ImageBind voice joins the voice side as ib_scale * unit(unit(ibv) - mu_ib).
    vextra (RF-L2-045): more unit-normalised voice blocks appended after ECAPA (e.g. the Whisper encoder mean)."""
    vb = [_u(sam), _u(r2), _u(btc)] + [_u(e) for e in vextra] + ([] if ibv is None else [ib_scale * _u(_u(ibv) - mu_ib)])
    f = torch.tensor(np.hstack([_u(clip), _u(ibf)]).astype(np.float32)); v = torch.tensor(np.hstack(vb).astype(np.float32))
    return np.mean([(F.normalize(m.f(f), dim=-1) * F.normalize(m.v(v), dim=-1)).sum(1).numpy() for m in models], 0)
class WhisperVoiceExtractor:
    name = 'openai/whisper-large-v3'

    def __init__(self, max_sec=30):
        import transformers as T
        self.max_sec = max_sec; self.fe = T.WhisperFeatureExtractor.from_pretrained(self.name, revision=HF_REV[self.name])
        self.m = T.WhisperModel.from_pretrained(self.name, revision=HF_REV[self.name], torch_dtype=torch.float16).encoder.to(DEVICE).eval(); self.dim = self.m.config.d_model

    def _one(self, w):
        x = self.fe(w, sampling_rate=16000, return_tensors='pt').input_features.to(DEVICE, torch.float16)
        h = self.m(x).last_hidden_state[0]
        n = max(1, min(h.shape[0], int(np.ceil(len(w) / 16000 / 30 * h.shape[0]))))
        return h[:n].float().mean(0).cpu().numpy()

    @torch.inference_mode()
    def voices(self, paths):
        def fn(ps):
            out = []
            for p in ps:   # one clip at a time
                w, st = load_wave(p)
                out.append(np.full(self.dim, np.nan, np.float32) if w is None else self._one(w[:16000 * self.max_sec]).astype(np.float32))
            return out
        return _cached_map(paths, fn, self.dim)
class E2EExtractor:
    """All per-file embeddings the scorer needs; every file is embedded on its own (no batch padding, no file stats).
    RF-L2-059: vx = extra t3 voice blocks from the manifest (only 'whv3'); ages() = RF-L1-004 face / voice age (first column)."""

    def __init__(self, ckpts, vx=()):
        self.c, self.vx = ckpts, tuple(vx)
        assert set(self.vx) <= {'whv3'}, self.vx

    def ages(self, fpaths, vpaths):
        ag = AgeExtractor(); a = ag.faces(fpaths)[:, 0], ag.voices(vpaths)[:, 0]; del ag; torch.cuda.empty_cache(); return a

    def faces(self, paths):
        ex = L2Extractor(self.c['imagebind'], self.c['r221'], self.c['vgg']); vg, ibf, _ = ex.face_features(paths); del ex
        torch.cuda.empty_cache(); cl = ClipFaceExtractor(); clip = cl.faces(paths); del cl; torch.cuda.empty_cache()
        return dict(xf=vg, ibf=ibf, clip=clip)

    def voices(self, paths):
        ex = L2Extractor(self.c['imagebind'], self.c['r221'], self.c['vgg']); btc, ibv, r2, _ = ex.voice_features(paths); del ex
        torch.cuda.empty_cache()
        ib, MT = load_imagebind(self.c['imagebind']); params = add_lora(ib, MT, 8, 16)
        state = torch.load(self.c['lora'], map_location=DEVICE)
        for p, v in zip(params, state['params']): p.data.copy_(v)
        lora = embed_audio(ib, MT, paths); del ib, params; torch.cuda.empty_cache()
        vb = VB2Extractor(self.c['sam']); sam = vb2_voices(vb, paths, 60); del vb; torch.cuda.empty_cache()
        out = dict(xv=btc, ibv=ibv, r221=r2, lora=lora, sam=sam)
        if 'whv3' in self.vx:
            wx = WhisperVoiceExtractor(); out['whv3'] = wx.voices(paths); del wx; torch.cuda.empty_cache()
        return out


# =========================================================================== RF-FINAL: the submitted system (RF-L2-059)
# Every pair is scored on its own from fixed parameters learned on the training data (final_params.npz, written by
# make_final_release.py); nothing is fitted, normalised or looked up across pairs at test time.
#   t3   cosine of the QV-Whisper projector: face [CLIP ViT-L/14 || ImageBind] x voice [SimAM-ResNet100 || ResNet221 || ECAPA || Whisper]
#   ib   ImageBind face x ImageBind audio with LoRA C1b, each centred by its training mean
#   age  -|ViT-age(face) - b(audeering age(voice))|, no_gender files only
#   conditions: P(male) of the face (VGG-Face) and of the voice (ECAPA) from logistic probes, their agreement, the file's protocol
#   nf, nv (RF-L2-092, when the manifest lists them): log norm of the projected face / voice embedding before L2 normalisation
#        (mean over the projector seeds), a per-input property of each file; no cohort, no test statistic
# gender files: logistic regression on (t3, ib[, nf, nv]); no_gender files: logistic regression on streams + conditions + products.
VERSION = "RF-FINAL-v2"


@torch.no_grad()
def qf_norms(models, clip, ibf, sam, r2, btc, vextra=()):
    """RF-L2-092: per file, mean over the projector seeds of log ||projection|| before L2 normalisation (face side, voice side)."""
    f = torch.tensor(np.hstack([_u(clip), _u(ibf)]).astype(np.float32)); v = torch.tensor(np.hstack([_u(sam), _u(r2), _u(btc)] + [_u(e) for e in vextra]).astype(np.float32))
    return (np.mean([torch.log(m.f(f).norm(dim=1)).numpy() for m in models], 0), np.mean([torch.log(m.v(v).norm(dim=1)).numpy() for m in models], 0))


class FinalScorer:
    def __init__(self, art):
        art = Path(art); self.man = read_json(art / 'manifest_final.json')
        with np.load(art / 'final_params.npz') as z:
            self.p = {k: z[k] for k in z.files}
        self.vx = [b['block'] for b in self.man['t3_voice_extra']]
        dv = 256 + 256 + 192 + sum(int(b['dim']) for b in self.man['t3_voice_extra'])
        self.proj = []
        for sd in torch.load(art / 'projector_Q.pt', map_location='cpu'):
            m = ProjQ(768 + 1024, dv, self.man['projector']); m.load_state_dict(sd); self.proj.append(m.eval())

    def _lr(self, name, X):   # logistic regression decision values (fused scaler + coefficients)
        p = self.p; return ((X - p[f'{name}_mean']) / p[f'{name}_scale']) @ p[f'{name}_coef'] + p[f'{name}_b']

    def score(self, x, proto):
        """x: per-pair rows (xf VGG-Face, ibf, clip, age_f; xv ECAPA, lora, r221, sam, whv3, age_v). Returns lower-is-same."""
        p = self.p; fill = lambda k, X: fill_nonfinite(X, p[f'fill_{k}'])[0]
        xf, xv, ibf, r2 = fill('xf', x['xf']), fill('xv', x['xv']), fill('ib_face', x['ibf']), fill('r221', x['r221'])
        cl, sam, vext = fill('clip', x['clip']), fill('sam', x['sam']), [fill(b, x[b]) for b in self.vx]
        s = {'t3': t3_scores(self.proj, cl, ibf, sam, r2, xv, vextra=vext),
             'ib': (_unit(ibf - p['mu_ibf']) * _unit(fill('lora', x['lora']) - p['fill_lora'])).sum(1)}
        if 'nf' in self.man['streams_g'] or 'nf' in self.man['streams_ng']:   # RF-L2-092
            s['nf'], s['nv'] = qf_norms(self.proj, cl, ibf, sam, r2, xv, vext)
        pf = 1 / (1 + np.exp(-(((xf - p['prep_mf']) / p['prep_sf']) @ p['prep_P']).astype(np.float32) @ p['gf_coef'] - p['gf_b']))
        pv = 1 / (1 + np.exp(-((xv - p['prep_mv']) / p['prep_sv']).astype(np.float32) @ p['gv_coef'] - p['gv_b']))
        s.update(p_face_male=pf, p_voice_male=pv, gender_agree=pf * pv + (1 - pf) * (1 - pv), protocol_gender=np.full(len(xf), float(proto == 'gender')))
        if proto == 'gender':   # the file's protocol label set by the organisers (declared)
            out = -self._lr('fg', np.stack([s[k] for k in self.man['streams_g']], 1))
        else:
            a_f = np.where(np.isfinite(x['age_f']), x['age_f'], p['age_fill'][0]); a_v = np.where(np.isfinite(x['age_v']), x['age_v'], p['age_fill'][1])
            s['age'] = -np.abs(a_f - np.polyval(p['age_b'], a_v))
            out = -self._lr('fn', fuser_matrix4(s, self.man['streams_ng']))
        if not np.isfinite(out).all(): raise ValueError('non-finite scores')
        return out
